-- aar/w3/aar_row_669_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for W1's grade, then the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 669 (operational_doc v148, section 29, paragraph LAYERS BEFORE A CORPUS FINDING, written 10:32 CST 2026-11-27) and its ask_aar_builders row.
-- Values are from the Wall posts named in sources (read by W3), W3's own thread, audit_log rows 42993 and 42994 and SQL readback of operational_doc by W3 at 10:32 CST 2026-11-27.
-- md5_written holds the md5 of operational_doc v148 content. W1 states it in full on Wall 12761 (preview) and Wall 12763 (readback).
-- ASK 670 is not in this draft: it is a seat 36 note change and its facts are the coordinator's.
-- objective_met is 'in part': written and read back; unexercised until the next corpus finding.
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (669, '0', $t$ASK 669: layers before a corpus finding: a paragraph added to operational_doc section 29$t$,
  $t$W3's finding 6 of 2026-11-25 called two honestly marked Layer 4 steps a flaw in the corpus, and went to the operator before the verses were taken through the layers. On 2026-11-27 (09:55 CST) the operator ordered the layers applied to the scriptures in question first; by the layers one part was not a flaw and the other misplaced the defect (ASK 668). The coordinator proposed a standing rule (Wall 12752). Change: one paragraph, LAYERS BEFORE A CORPUS FINDING, added to operational_doc section 29 after the one-grader paragraph and before BEFORE THE BUILD. It says: for any finding that names a corpus row (a sight, a guard or a conclusion) as a flaw, the seat that made it takes the verse itself through the four layers in the words of Chapter 2 of the book read by SQL and posts the reading on the Wall; one seat that did not make the finding confirms every quote, word number and gloss by SQL and states the layer of each step; only then does the finding go to the operator, with the reading; an honestly marked Layer 4 with its footing shown is not a flaw for want of a row, and an error in its footing still is. Expected effect: no corpus finding reaches the operator unread by the layers or unchecked by a second seat. Not changed: any other op doc text, the Wall manual, the engine manual, the engine, any corpus row.$t$,
  'in part',
  $t$WRITTEN AND READ BACK: operational_doc v148 inserted by one guarded call (base md5 and result md5 both tested in the call); W3 read back equal to the preview (Wall 12762); W1 read back MATCH (Wall 12763). IN PART because the rule is unexercised until the next corpus finding. MISTAKES: (1) W3: the last sentence of draft 1, "is not a flaw", would have cleared Sight 266, whose Layer 4 step showed its footing yet carried a wrong word number; W1 bounded it (R1, Wall 12758). (2) W1: Wall 12758 gave R1 as 37 characters without counting; measured 52, corrected by W1 on Wall 12759. NOTE ON THE APPROVAL: the operator's "approved" of 10:26 CST came before R1 changed the text, so W3 showed him the exact paragraph on a card and wrote on his press of 10:31 CST. NOT CHECKED by W3: whether each seat has put the rule in its md_notes (W4 reported it has; W3's note holds it as its operator rule of 2026-11-25).$t$,
  '12752, 12754, 12755, 12757, 12758, 12759, 12760, 12761, 12762, 12763',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$Verbatim, 2026-11-27. In the W3 thread, 09:55 CST: "before to apply the layers to  scriptures in question". In the project chat, 10:26 CST, in answer to the coordinator's post on ASKs 669 to 671 (relayed to W3 by the coordinator with his message attached): "approved". In the W3 thread, 10:31 CST: he pressed "Write it now" on the card "Write this paragraph into the operational doc, section 29?".$t$::text),
  $j${"answer": "Write it now", "question": "Write this paragraph into the operational doc, section 29?", "thread": "W3", "press_times": {"Write it now": "10:31 CST 2026-11-27"}, "card_id_last": "cmsg_017ZQamDMHrS6fqMHnQDVo58MmBqjuffpCrLBjDeFR6Wx9", "source": "W3's own thread; press as posted on Wall 12762"}$j$::jsonb,
  'W3',
  $j${"md5": null, "path": null, "note": "no plan file: the proposal is the coordinator's Wall 12752, reviewed by W1 (Wall 12754) and W3 (Wall 12755); the coordinator chose section 29.", "source": "Wall 12752, 12754, 12755"}$j$::jsonb,
  $j$[{"path": "ask669/w3/opdoc_pair_669_draft2.md", "md5": "e1a9b53fcbc151f32a0a6090c231d667", "what": "the old and new strings, draft 2, W1's R1 applied; confirmed by W1 (Wall 12761)"}, {"path": "ask669/w3/opdoc_pair_669_draft1.md", "md5": "4add4af476d9c91582ce17f069d34571", "what": "draft 1, W1 PASS WITH R1 (Wall 12758)"}]$j$::jsonb,
  $j${"operational_doc": "the table is append-only: to undo, insert a version 149 whose content is v148 with the NEW string of the pair replaced by its OLD string, which gives the v147 content (md5 125698750d9037244ae01fe975b129a9, 76,685); on the operator's word only.", "rehearsed": "no", "source": "W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "pair draft 1 PASS WITH R1 (Wall 12758); draft 2 CONFIRMED, preview of v148 stated in full (Wall 12761); READBACK MATCH (Wall 12763)", "wall_id": 12761, "md5_graded": "bb190d3b8a2f6e95eb6f55da13f7a712", "verdict_norm": "PASS", "source": "Wall 12761"}]$j$::jsonb,
  ARRAY['bb190d3b8a2f6e95eb6f55da13f7a712'], '[42993, 42994]'::jsonb,
  $j$[{"kind": "operational_doc version", "name": "operational_doc v148, column content, 10:32 CST 2026-11-27", "before": "v147, md5 125698750d9037244ae01fe975b129a9, 76,685: section 29 runs from the one-grader paragraph straight to BEFORE THE BUILD", "after": "v148, md5 bb190d3b8a2f6e95eb6f55da13f7a712, 77,496 (811 added): the paragraph LAYERS BEFORE A CORPUS FINDING stands between them; nothing removed or reworded"}]$j$::jsonb,
  $j$[{"name": "pair count and preview", "result": "the OLD string occurs exactly once in v147; preview computed by SQL from the exact pair before the card (bb190d3b, 77,496); W1 computed the same independently (Wall 12761); the insert returned the same md5 and length", "source": "Wall 12760, 12761, 12762"}, {"name": "run check", "result": "W4 read n8n at 10:32 CST: no execution running on any workflow; last engine execution 42528", "source": "W4's message to W3, 10:32 CST 2026-11-27; Wall 12762"}, {"name": "NOT RUN", "result": "no rehearsal of the undo; the rule has not yet been applied to a finding", "source": "W3"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "operational_doc v148 MATCH: bb190d3b8a2f6e95eb6f55da13f7a712, 77,496, one row, highest version", "wall_id": 12763, "source": "Wall 12763"}]$j$::jsonb,
  $j${"case": "NOT A RUN CHANGE.", "runs": [], "mark_for_the_next_run": "none: the rule binds seats, not the engine. Its first exercise is the next finding that names a corpus row as a flaw: the layered reading and the second seat's check are on the Wall before the operator sees the finding.", "not_shown": "any exercise of the rule.", "source": "Wall 12763"}$j$::jsonb,
  $j${"op_doc": "v148, section 29, one paragraph added (bb190d3b8a2f6e95eb6f55da13f7a712, 77,496)", "engine_manual": "none", "note": "no Wall manual change."}$j$::jsonb,
  'read back', $j$[12752, 12754, 12755, 12757, 12758, 12759, 12760, 12761, 12762, 12763]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W3'], $j$[{"seat": "W3", "what": "drafted the paragraph and wrote operational_doc v148 on the operator's card", "wall_id": 12762}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
